import { mkdir, writeFile } from "node:fs/promises"
import { dirname, join, relative, sep } from "node:path"

export async function writeEmbeddedAssets(
  directory: string,
  modulePath: string,
  exportName: string,
) {
  const files = [
    ...new Bun.Glob("**/*").scanSync({ cwd: directory, onlyFiles: true }),
  ].sort()
  const portable = (path: string) => path.split(sep).join("/")
  const generated = [
    "// @ts-nocheck -- Bun file imports resolve to embedded paths.",
    "// Generated by scripts/write-embedded-assets.ts; do not edit.",
    ...files.map(
      (file, index) =>
        `import asset${index} from ${JSON.stringify(`./${portable(relative(dirname(modulePath), join(directory, file)))}`)} with { type: "file" }`,
    ),
    `export const ${exportName}: Record<string, string> = {`,
    ...files.map(
      (file, index) => `  ${JSON.stringify(portable(file))}: asset${index},`,
    ),
    "}\n",
  ]
  await mkdir(dirname(modulePath), { recursive: true })
  await writeFile(modulePath, generated.join("\n"))
}
